{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Ketoconazole, the closest retrieved analogue (Morgan 0.5532), has mean oral bioavailability of approximately 75% in healthy volunteers, directly supporting F >= 20% for the azole-dioxolane-piperazine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Posaconazole delayed-release tablet had an absolute bioavailability of around 50% in healthy volunteers, supporting high F for the triazolone-piperazine-dioxolane scaffold shared with the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Posaconazole oral suspension had an absolute bioavailability of 16% (8-27%) in immunocompromised pediatric patients, a threshold-relevant low value, but this is formulation- and population-specific and is outweighed by high-F evidence from the same scaffold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "Voriconazole, a triazole antifungal, has a mean absolute oral bioavailability of approximately 96% in humans, providing class-level support for high F despite low structural similarity to the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted high: the closest analogue ketoconazole has ~75% oral bioavailability and the related posaconazole tablet ~50%; the only sub-20% value is a formulation/population-specific posaconazole suspension result, so F >= 20% is well supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule in the retrieved evidence.",
    "Itraconazole bioavailability is formulation- and food-dependent, so a single F value is not captured.",
    "Posaconazole suspension low F in pediatric/immunocompromised patients may not transfer to adult itraconazole capsule use."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

